  const pr = await op('va', 'upload_chunk', { entryId: EP, mixKey: m1.key, offset: 0, data: Buffer.alloc(3 * 262144).toString('base64') }); ok('and it completes as a Private video', pr.body.done && yt.state.videos.get(pr.body.youtubeVideoId).privacyStatus === 'private', pr.body);
